  ['filter[minPrice]=1000&filter[maxPrice]=2000&filter[inStock]=true&sort=title',
   "select b.id from book b where b.published and b.price_cents between 1000 and 2000 and b.stock > 0 order by b.title asc, b.id asc", []],
  ['filter[inStock]=false&filter[author]=Frank%20Herbert',
   "select b.id from book b join author a on a.id=b.author_id where b.published and b.stock=0 and a.name='Frank Herbert' order by b.id", []],
  ['filter[publishedAfter]=1969-01-01&filter[publishedBefore]=1969-12-31',
   "select b.id from book b where b.published and b.published_at between '1969-01-01' and '1969-12-31' order by b.id", []],
  ['sort=publishedAt',
   "select b.id from book b where b.published order by b.published_at asc nulls last, b.id asc", []],
  ['sort=-publishedAt,-priceCents',
   "select b.id from book b where b.published order by b.published_at desc, b.price_cents desc, b.id asc", []],
];
foreach ($cases as [$query, $sql, $params]) {
  $expected = array_map('intval', array_column($pdo->query($sql)->fetchAll(PDO::FETCH_ASSOC), 'id'));
