cat > /tmp/bookshop-tests/payment.php <<'EOF'
<?php
// Exercises PaymentGateway::charge() with a mock HTTP client: accepted, declined, failing, unreachable.
require '/work/vendor/autoload.php';

use App\Api\ApiException;
use App\Payment\PaymentGateway;
use Symfony\Component\HttpClient\MockHttpClient;
use Symfony\Component\HttpClient\Response\MockResponse;

$cases = [
    'accepted' => [new MockResponse('{"status":"accepted"}', ['http_code' => 200]), null],
    'declined' => [new MockResponse('{"status":"declined"}', ['http_code' => 200]), 402],
    'declined with 402 http' => [new MockResponse('{"status":"declined"}', ['http_code' => 402]), 402],
    'accepted but 500' => [new MockResponse('{"status":"accepted"}', ['http_code' => 500]), 502],
    'garbage' => [new MockResponse('<html>oops</html>', ['http_code' => 200]), 502],
    'unknown status' => [new MockResponse('{"status":"maybe"}', ['http_code' => 200]), 502],
    'transport error' => [new MockResponse('', ['error' => 'Connection refused']), 502],
];
foreach ($cases as $name => [$response, $expected]) {
    $gateway = new PaymentGateway(new MockHttpClient($response));
    try {
        $gateway->charge(1, 1000);
        $actual = null;
    } catch (ApiException $e) {
        $actual = $e->getStatus();
    }
    echo ($actual === $expected ? 'PASS' : 'FAIL'), " $name: expected ", var_export($expected, true), " got ", var_export($actual, true), "\n";
}
EOF
